const GRADES = [
    ['D-', 0],
    ['D', 5],
    ['D+', 10],
    ['C-', 20],
    ['C', 30],
    ['C+', 40],
    ['B-', 60],
    ['B', 80],
    ['B+', 100],
    ['A-', 150],
    ['A', 200],
    ['A+', 300],
    ['S-', 500],
    ['S', 800],
    ['S+', 1200],
    ['SS', 2000],
    ['SS+', 3500],
    ['SSS', 5000]
];
/** v2 is an open-source impact score, not a ranking of individual ability. */
function calculateRating(profile, repos, date) {
    const stars = repos.reduce((sum, repo) => sum + repo.stars, 0);
    const forks = repos.reduce((sum, repo) => sum + repo.forks, 0);
    const starsPerRepo = repos.length ? stars / repos.length : 0;
    const ageYears = Math.max(0, (Date.parse(date) - Date.parse(profile.createdAt)) / 31557600000);
    const breakdown = {
        repositories: repos.length,
        stars: stars * 0.5,
        commits: Math.min(profile.commits * 0.1, 300),
        issues: Math.min(profile.issues * 0.05, 50),
        pullRequests: Math.min(profile.pullRequests * 0.1, 50),
        followers: profile.followers * 0.3,
        contributedRepositories: profile.contributedTo * 2,
        forks: forks * 0.2,
        starMilestone: stars >= 10000
            ? 2000
            : stars >= 5000
                ? 1000
                : stars >= 1000
                    ? 500
                    : stars >= 500
                        ? 200
                        : stars >= 100
                            ? 50
                            : 0,
        averageStars: Math.min(starsPerRepo * 2, 100),
        longevity: Math.min(ageYears * 5, 25)
    };
    const score = Math.round(Object.values(breakdown).reduce((a, b) => a + b, 0));
    let index = 0;
    for (let i = 0; i < GRADES.length; i++)
        if (score >= GRADES[i][1])
            index = i;
    const current = GRADES[index];
    const next = GRADES[index + 1];
    return {
        version: 'v2',
        grade: current[0],
        score,
        nextGrade: next?.[0] ?? null,
        nextScore: next?.[1] ?? null,
        progress: next ? (score - current[1]) / (next[1] - current[1]) : 1,
        breakdown: Object.fromEntries(Object.entries(breakdown).map(([key, value]) => [
            key,
            Math.round(value * 100) / 100
        ]))
    };
}

const REPOSITORIES_QUERY = `query StarTrackRepositories($owner: String!, $cursor: String) {
  repositoryOwner(login: $owner) {
    repositories(first: 50, after: $cursor, privacy: PUBLIC, ownerAffiliations: [OWNER], orderBy: {field: NAME, direction: ASC}) {
      nodes {
        name nameWithOwner description url stargazerCount forkCount isFork isArchived createdAt
        primaryLanguage { name } watchers { totalCount }
        issues { totalCount } closedIssues: issues(states: [CLOSED]) { totalCount }
        pullRequests { totalCount } mergedPullRequests: pullRequests(states: [MERGED]) { totalCount }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}`;
const PROFILE_QUERY = `query StarTrackProfile($username: String!, $from: DateTime!, $to: DateTime!) {
  user(login: $username) {
    login name createdAt followers { totalCount } following { totalCount }
    repositoriesContributedTo(first: 1, privacy: PUBLIC, includeUserRepositories: true) { totalCount }
    contributionsCollection(from: $from, to: $to) {
      totalCommitContributions totalIssueContributions totalPullRequestContributions totalPullRequestReviewContributions
      contributionCalendar { totalContributions weeks { contributionDays { date contributionCount } } }
    }
  }
}`;
/** Retry transient failures only; pagination never returns a partial success. */
async function withRetry(request, sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))) {
    for (let attempt = 0;; attempt++) {
        try {
            return await request();
        }
        catch (error) {
            const e = error;
            const retryAfter = Number(e.response?.headers?.['retry-after'] ?? 0);
            const transient = e.status === 429 ||
                (e.status !== undefined && e.status >= 500) ||
                (e.status === 403 && retryAfter > 0);
            if (!transient || attempt >= 2 || retryAfter > 30)
                throw error;
            await sleep(Math.max(retryAfter * 1000, 1000 * 2 ** attempt));
        }
    }
}
function githubClient(octokit) {
    return {
        graphql: (query, variables) => withRetry(() => octokit.graphql(query, variables)),
        organizations: (username) => withRetry(async () => {
            const orgs = await octokit.paginate(octokit.orgs.listForUser, {
                username,
                per_page: 100
            });
            return orgs.map((org) => org.login);
        })
    };
}
async function fetchRepositories(client, owner) {
    const repos = [];
    let cursor = null;
    const seen = new Set();
    for (;;) {
        const response = await client.graphql(REPOSITORIES_QUERY, { owner, cursor });
        if (!response.repositoryOwner)
            throw new Error(`GitHub owner not found: ${owner}`);
        const page = response.repositoryOwner.repositories;
        for (const repo of page.nodes) {
            if (!repo)
                throw new Error(`Incomplete repository response for ${owner}`);
            repos.push({
                name: repo.name,
                owner: repo.nameWithOwner.split('/')[0],
                fullName: repo.nameWithOwner,
                description: repo.description ?? '',
                url: repo.url,
                language: repo.primaryLanguage?.name ?? '—',
                stars: repo.stargazerCount,
                forks: repo.forkCount,
                watchers: repo.watchers.totalCount,
                issues: repo.issues.totalCount,
                closedIssues: repo.closedIssues.totalCount,
                pullRequests: repo.pullRequests.totalCount,
                mergedPullRequests: repo.mergedPullRequests.totalCount,
                isFork: repo.isFork,
                isArchived: repo.isArchived,
                createdAt: repo.createdAt
            });
        }
        if (!page.pageInfo.hasNextPage)
            return repos;
        cursor = page.pageInfo.endCursor;
        if (!cursor || seen.has(cursor))
            throw new Error(`Invalid pagination cursor for ${owner}`);
        seen.add(cursor);
    }
}
function buildSnapshot(config, profile, repositories, organizations, collectedAt, from) {
    const excluded = new Set(config.repositories.exclude.map((name) => name.toLowerCase()));
    const repos = [
        ...new Map(repositories.map((repo) => [repo.fullName.toLowerCase(), repo])).values()
    ]
        .filter((repo) => (config.repositories.include_forks || !repo.isFork) &&
        (config.repositories.include_archived || !repo.isArchived) &&
        !excluded.has(repo.fullName.toLowerCase()))
        .sort((a, b) => a.fullName.localeCompare(b.fullName, 'en'));
    const sum = (key) => repos.reduce((total, repo) => total + repo[key], 0);
    const languages = {};
    for (const repo of repos)
        if (repo.language !== '—')
            languages[repo.language] = (languages[repo.language] ?? 0) + 1;
    const topLanguage = Object.entries(languages).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'en'))[0]?.[0] ?? 'None';
    const selected = config.featured.length
        ? config.featured.map((item) => {
            const repo = repos.find((repo) => repo.fullName.toLowerCase() === item.repo.toLowerCase());
            if (!repo)
                throw new Error(`Featured repository ${item.repo} is outside the selected public scope or excluded. Check organizations and repository filters.`);
            return { ...repo, description: item.description ?? repo.description };
        })
        : [...repos]
            .sort((a, b) => b.stars - a.stars || a.fullName.localeCompare(b.fullName, 'en'))
            .slice(0, 3);
    return {
        schemaVersion: 2,
        sourceKey: sourceKey(config),
        collectedAt,
        window: { from, to: collectedAt },
        scope: { username: profile.login, organizations },
        profile,
        repositories: repos,
        featured: selected,
        totals: {
            stars: sum('stars'),
            repositories: repos.length,
            forks: sum('forks'),
            watchers: sum('watchers'),
            issues: sum('issues'),
            pullRequests: sum('pullRequests'),
            issueCloseRate: sum('issues')
                ? (sum('closedIssues') / sum('issues')) * 100
                : 0,
            prMergeRate: sum('pullRequests')
                ? (sum('mergedPullRequests') / sum('pullRequests')) * 100
                : 0,
            topLanguage,
            languages
        },
        rating: calculateRating(profile, repos, collectedAt)
    };
}
async function collectStats(client, config, now = new Date(), log = () => { }) {
    const to = now.toISOString();
    // 365 days avoids an invalid >1-year GraphQL interval around leap days.
    const from = new Date(now.getTime() - 365 * 86400000).toISOString();
    const { user } = await client.graphql(PROFILE_QUERY, { username: config.username, from, to });
    if (!user)
        throw new Error(`GitHub user not found: ${config.username}`);
    const c = user.contributionsCollection;
    const profile = {
        login: user.login,
        name: user.name || user.login,
        createdAt: user.createdAt,
        followers: user.followers.totalCount,
        following: user.following.totalCount,
        contributedTo: user.repositoriesContributedTo.totalCount,
        contributions: c.contributionCalendar.totalContributions,
        commits: c.totalCommitContributions,
        issues: c.totalIssueContributions,
        pullRequests: c.totalPullRequestContributions,
        reviews: c.totalPullRequestReviewContributions,
        calendar: c.contributionCalendar.weeks
            .flatMap((week) => week.contributionDays.map((day) => ({
            date: day.date,
            count: day.contributionCount
        })))
            .filter((day) => day.date <= to.slice(0, 10))
    };
    const organizations = config.scope === 'all'
        ? [
            ...new Set((config.organizations ?? (await client.organizations(user.login))).map((org) => org.toLowerCase()))
        ]
            .filter((org) => org !== user.login.toLowerCase())
            .sort()
        : [];
    const repos = [];
    for (const owner of [user.login, ...organizations]) {
        log(`Collecting public repositories: ${owner}`);
        repos.push(...(await fetchRepositories(client, owner)));
    }
    return buildSnapshot(config, profile, repos, organizations, to, from);
}

